class SettingsScreen extends StatefulWidget {final GameStore store;const SettingsScreen({super.key,required this.store});@override State<SettingsScreen> createState()=>_SettingsScreenState();}
class _SettingsScreenState extends State<SettingsScreen>{Widget toggle(String title,String sub,bool value,ValueChanged<bool> change)=>Card(child:SwitchListTile(value:value,onChanged:(v){change(v);widget.store.save();setState((){});},activeTrackColor:lime,title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(sub),secondary:Icon(value?Icons.toggle_on:Icons.toggle_off,color:cyan)));
@override Widget build(BuildContext context)=>Scaffold(body:GridBackground(child:ListView(padding:const EdgeInsets.all(18),children:[const AppTitle('PENGATURAN','Atur pengalaman bermainmu'),const SizedBox(height:20),toggle('Efek Suara','Umpan balik saat menjawab',widget.store.sound,(v)=>widget.store.sound=v),toggle('Animasi','Gerakan dan efek visual',widget.store.animation,(v)=>widget.store.animation=v),toggle('Mode Sulit','Urutan soal dibuat acak',widget.store.hard,(v)=>widget.store.hard=v),const SizedBox(height:18),OutlinedButton.icon(onPressed:()=>showDialog(context:context,builder:(c)=>AlertDialog(title:const Text('Reset progress?'),content:const Text('Skor, bintang, dan level terbuka akan dihapus.'),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('BATAL')),FilledButton(onPressed:()async{await widget.store.reset();if(c.mounted)Navigator.pop(c);},child:const Text('RESET'))])),icon:const Icon(Icons.restart_alt_rounded),label:const Text('RESET PROGRESS'),style:OutlinedButton.styleFrom(foregroundColor:Colors.redAccent,minimumSize:const Size.fromHeight(52),side:const BorderSide(color:Colors.redAccent)))])) );}
